// Step 1 verification harness: runs the WASM module under Node (pthreads via
// worker_threads - no cross origin isolation needed here, unlike the browser).
//
// Gates:
//   1. in-memory generation completes (timing + heap size reported)
//   2. 4 seeded scrambles solve to the SAME DEPTHS as the native build
//   3. state_after_moves matches the native module (binding + rotations)
//   4. solve_position on the run-0 placements (web/tests/testdata/run0_placements.json,
//      generated by tools/make_placements.py) solves to the run-0 depth
//
// Run:  node web/node_test.js [--quick]
// --quick skips gate 2 (the scramble searches) and only does 3+4.

const fs = require('fs');
const path = require('path');

const MODULE_DIR = path.join(__dirname, '..', '..', 'build_web', 'bin');
const TESTDATA = path.join(__dirname, 'testdata', 'run0_placements.json');
const NATIVE_STATE = path.join(__dirname, 'testdata', 'run0_state.json');
const NUM_RUNS = 4;

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

// emscripten 6 embind returns std::vector as instances (size/get), not arrays
function vecToArray(v) {
    const out = [];
    for (let i = 0; i < v.size(); i++) out.push(v.get(i));
    return out;
}

async function drain(mod, handler) {
    // poll the event queue until the handler returns true
    for (;;) {
        for (const ev of vecToArray(mod.poll_events())) {
            if (handler(ev)) return;
        }
        await sleep(250);
    }
}

async function main() {
    const quick = process.argv.includes('--quick');
    const create = require(path.join(MODULE_DIR, 'puppetweb.js'));
    const mod = await create({});
    console.log(`module loaded, threads available: ${mod.num_threads ? 'n/a' : ''}`);

    // --- gate 1: generation -------------------------------------------------
    console.log('initializing (in-memory generation) ...');
    const t0 = Date.now();
    mod.initialize(['-r', String(NUM_RUNS), '-l', 'extra']);
    await drain(mod, ev => {
        if (ev.kind === 'stage') console.log(`  [stage] ${ev.text}`);
        return ev.kind === 'ready' || ev.kind === 'error';
    });
    const initSec = (Date.now() - t0) / 1000;
    const heapMB = (mod.wasmMemory ? mod.wasmMemory.buffer.byteLength : mod.HEAPU8.buffer.byteLength) / 1048576;
    const rssMB = process.memoryUsage().rss / 1048576;
    console.log(`initialized in ${initSec.toFixed(1)} s, heap ${heapMB.toFixed(0)} MB, node rss ${rssMB.toFixed(0)} MB, threads ${mod.num_threads()}`);

    // --- gate 2: the searches run and produce verified solutions -----------
    // (the scramble sequences themselves differ from the native build:
    // libstdc++ and libc++ use different uniform_int_distribution
    // algorithms - the depth cross-check happens on a fixed position in
    // gate 4; here we verify the solutions replay to solved)
    let scrambles = null;
    if (!quick) {
        console.log(`solving ${NUM_RUNS} seeded scrambles ...`);
        const t1 = Date.now();
        const depths = [];
        const runs = new Map();  // run idx -> scramble moves
        const times = new Map();
        mod.run();
        await drain(mod, ev => {
            if (ev.kind === 'scramble') {
                runs.set(ev.runIdx, vecToArray(ev.moves));
                times.set(ev.runIdx, Date.now());
                console.log(`  [run ${ev.runIdx}] scramble: ${ev.moves.size()} moves`);
            }
            if (ev.kind === 'solution') {
                depths.push(ev.depth);
                const sec = ((Date.now() - times.get(ev.runIdx)) / 1000).toFixed(1);
                console.log(`  [run ${ev.runIdx}] depth ${ev.depth} (${sec} s, ${ev.moves.size()} moves)`);
            }
            return depths.length >= NUM_RUNS;
        });
        console.log(`depths: ${depths.join(',')}   (informational - the scrambles differ from native)`);
        scrambles = Array.from(runs.values());
        fs.mkdirSync(path.join(__dirname, 'testdata'), {recursive: true});
        fs.writeFileSync(path.join(__dirname, 'testdata', 'scrambles.json'), JSON.stringify(scrambles));
        console.log(`total solve time: ${((Date.now() - t1) / 1000).toFixed(1)} s`);
    } else if (fs.existsSync(path.join(__dirname, 'testdata', 'scrambles.json'))) {
        scrambles = JSON.parse(fs.readFileSync(path.join(__dirname, 'testdata', 'scrambles.json')));
    }

    // --- gate 3: state_after_moves matches the native module ----------------
    if (scrambles) {
        const state = vecToArray(mod.state_after_moves(scrambles[0], []));
        console.log(`state_after_moves(run 0 scramble): [${state.join(', ')}]`);
        if (fs.existsSync(NATIVE_STATE)) {
            const native = JSON.parse(fs.readFileSync(NATIVE_STATE));
            if (native.join(',') !== state.join(',')) {
                console.log('STATE MISMATCH - the wasm rotations disagree with the native build!');
                process.exit(1);
            }
            console.log('state matches the native module');
        }
    }

    // --- gate 4: convert + solve the run-0 position --------------------------
    if (fs.existsSync(TESTDATA)) {
        const placements = JSON.parse(fs.readFileSync(TESTDATA));
        const result = mod.convert_position(placements.corners, placements.edges);
        if (!result.ok) {
            console.log(`CONVERT FAILED: ${result.message}`);
            process.exit(1);
        }
        const stateArr = vecToArray(result.state);
        console.log(`convert_position ok: [${stateArr.join(', ')}]`);
        console.log('solving the painted position ...');
        const t2 = Date.now();
        let solution = null;
        mod.solve_position(placements.corners, placements.edges);
        await drain(mod, ev => {
            if (ev.kind === 'solution') { solution = ev; return true; }
            return false;
        });
        console.log(`custom position solved: depth ${solution.depth} (${((Date.now() - t2) / 1000).toFixed(1)} s, ${solution.moves.size()} moves)`);
        if (solution.depth !== 18) {
            console.log('CUSTOM DEPTH MISMATCH - expected 18 (the depth of run 0)!');
            process.exit(1);
        }
    } else {
        console.log('(skipping gate 4: web/tests/testdata/run0_placements.json missing - generate it with tools/make_placements.py)');
    }

    console.log('ALL WASM GATES PASSED');
    process.exit(0);
}

main().catch(err => { console.error(err); process.exit(1); });
